(function () {
  'use strict';
  // When an IRA or employer-plan owner's required minimum distributions (RMDs) begin, and the cost of
  // delaying the first one to April 1 of the following year.
  //   RMD age by birth date (SECURE / SECURE 2.0). First RMD year = year that age is reached; for an
  //   employer plan, a non-5%-owner still working may wait until the year they retire.
  //   First RMD = Dec 31 balance of the prior year / Uniform Lifetime divisor at that year's age.
  //   On time: first RMD taken in year 1; second RMD = (B x (1 + r) - first RMD) / divisor(age + 1).
  //   Delayed: nothing in year 1; year 2 has the first RMD plus a second RMD of B x (1 + r) /
  //   divisor(age + 1), because the Dec 31 balance was not reduced by the first RMD.
  //   Federal tax each year = 2026 brackets on (that year's other taxable income + RMDs).
  // Checked in Node (scratch tests): born 1953-08-15 -> 73, first RMD 2026, deadline April 1, 2027.
  // $400,000 at 5%, MFJ, $60,000 other taxable income: first RMD 400,000 / 26.5 = $15,094.34;
  // on time second RMD (420,000 - 15,094.34) / 25.5 = $15,878.65; delayed second RMD 420,000 / 25.5
  // = $16,470.59; taxes: on time 2026 tax on 75,094.34 = 2,480 + 12% x 50,294.34 = $8,515.32,
  // 2027 on 75,878.65 = $8,609.44; delayed 2026 on 60,000 = $6,704, 2027 on 91,564.93 = $10,491.79.
  // Start ages: born 1949-06-30 -> 70 1/2 in 2019; 1949-07-01 -> 72 in 2021; 1950 -> 72; 1951 and
  // 1959 -> 73; 1960 -> 75.
  //
  // ---- IRS rules and 2026 tax figures --------------------------------------------------------
  // RMD age (SECURE Act 2019, SECURE 2.0 Act 2022 sec. 107, IRS Pub. 590-B): born before July 1,
  // 1949: 70 1/2; July 1, 1949-1950: 72; 1951-1959: 73; 1960 or later: 75.
  // Uniform Lifetime Table: IRS Pub. 590-B (2025), Appendix B, Table III (distribution years 2022+),
  // compared programmatically with the IRS text. Key = age at year-end.
  var UNIFORM = {
    72: 27.4, 73: 26.5, 74: 25.5, 75: 24.6, 76: 23.7, 77: 22.9, 78: 22.0, 79: 21.1, 80: 20.2,
    81: 19.4, 82: 18.5, 83: 17.7, 84: 16.8, 85: 16.0, 86: 15.2, 87: 14.4, 88: 13.7, 89: 12.9,
    90: 12.2, 91: 11.5, 92: 10.8, 93: 10.1, 94: 9.5, 95: 8.9, 96: 8.4, 97: 7.8, 98: 7.3,
    99: 6.8, 100: 6.4, 101: 6.0, 102: 5.6, 103: 5.2, 104: 4.9, 105: 4.6, 106: 4.3, 107: 4.1,
    108: 3.9, 109: 3.7, 110: 3.5, 111: 3.4, 112: 3.3, 113: 3.1, 114: 3.0, 115: 2.9, 116: 2.8,
    117: 2.7, 118: 2.5, 119: 2.3, 120: 2.0
  };
  // Federal brackets, tax year 2026: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21).
  // Upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%. Used for both years compared.
  var TAX_YEAR = 2026;
  var BRACKETS = {
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  // ------------------------------------------------------------------------------------------

  function rmdStart(dob) {
    if (dob.y < 1949 || (dob.y === 1949 && dob.m < 7)) return { label: '70½', year: dob.y + 70 + (dob.m >= 7 ? 1 : 0) };
    var a = dob.y <= 1950 ? 72 : dob.y <= 1959 ? 73 : 75;
    return { label: String(a), year: dob.y + a };
  }
  function divisor(age) { return age >= 120 ? UNIFORM[120] : UNIFORM[age] || null; }
  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) tax += (Math.min(taxable, upper) - lower) * RATES[i];
      lower = upper;
    }
    return tax;
  }
  // On-time vs delayed first RMD for a first RMD year at age `age`.
  function tradeOff(balance, rate, age, other1, other2, status) {
    var d1 = divisor(age), d2 = divisor(age + 1);
    if (!d1 || !d2) return null;
    var first = Math.min(balance, balance / d1), grown = balance * (1 + rate);
    var onTime2 = Math.max(0, grown - first) / d2, delayed2 = grown / d2;
    var lim = BRACKETS[status];
    var a = { y1: first, y2: onTime2, t1: bracketTax(other1 + first, lim), t2: bracketTax(other2 + onTime2, lim) };
    var b = { y1: 0, y2: first + delayed2, t1: bracketTax(other1, lim), t2: bracketTax(other2 + first + delayed2, lim) };
    return { first: first, onTime: a, delayed: b };
  }

  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
    if (!m) return null;
    var d = { y: +m[1], m: +m[2], d: +m[3] };
    return d.m >= 1 && d.m <= 12 && d.d >= 1 && d.d <= 31 ? d : null;
  }
  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function cell(tr, text, tag) { var c = document.createElement(tag || 'td'); c.textContent = text; tr.appendChild(c); }

  function clear() {
    ['ybAge', 'ybFirstYear', 'ybDeadline', 'ybFirstAmt'].forEach(function (id) { set(id, '–'); });
    document.getElementById('ybCompare').textContent = '';
    set('ybNote', ''); set('ybCompareNote', '');
  }

  function update() {
    var dob = parseDate(document.getElementById('ybDob').value), type = document.getElementById('ybType').value,
        retireRaw = document.getElementById('ybRetire').value.trim(), retire = retireRaw === '' ? null : Math.round(parseFloat(retireRaw)),
        balance = num('ybBalance'), rate = num('ybRate'), other1 = num('ybIncome1'), other2 = num('ybIncome2'), status = document.getElementById('ybStatus').value;
    var error = document.getElementById('ybError'), msg = '';
    if (!dob || dob.y < 1920 || dob.y > 2010) msg = 'Enter a date of birth from 1920 to 2010.';
    else if (retire !== null && (isNaN(retire) || retire < 1990 || retire > 2100)) msg = 'Enter a retirement year from 1990 to 2100, or leave it blank.';
    else if ([balance, rate, other1, other2].some(isNaN) || balance < 0 || other1 < 0 || other2 < 0 || rate < -50 || rate > 30)
      msg = 'Enter a non-negative balance and income, and a return from -50% to 30%.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clear(); return; }

    var s = rmdStart(dob), firstYear = s.year, worked = false;
    if (type === 'plan' && retire !== null && retire > s.year) { firstYear = retire; worked = true; }
    var age = firstYear - dob.y; // age on birthday in the first RMD year
    set('ybBalYear', String(firstYear - 1));
    set('ybInc1Year', String(firstYear));
    set('ybInc2Year', String(firstYear + 1));
    set('ybAge', s.label);
    set('ybFirstYear', String(firstYear));
    set('ybDeadline', 'April 1, ' + (firstYear + 1));

    var notes = [];
    if (worked) notes.push('Because you are still working, RMDs from this employer plan start in ' + firstYear + ', the year you retire (age ' + age + '). This does not apply to IRAs or if you own more than 5% of the business.');
    else notes.push('You reach ' + s.label + ' in ' + firstYear + '. Your first RMD is for ' + firstYear + ' and every later RMD is due by December 31.');
    if (firstYear < TAX_YEAR) notes.push('Your RMDs have already started; use an RMD calculator for this year’s amount.');
    set('ybNote', notes.join(' '));

    var body = document.getElementById('ybCompare');
    body.textContent = '';
    var t = firstYear >= 2022 ? tradeOff(balance, rate / 100, age, other1, other2, status) : null;
    if (!t) {
      set('ybFirstAmt', '–');
      set('ybCompareNote', 'The comparison uses the Uniform Lifetime Table in effect from 2022, so it is shown only for first RMD years from 2022 on.');
      return;
    }
    set('ybFirstAmt', money(t.first));
    var y1 = firstYear, y2 = firstYear + 1;
    [['Take it by December 31, ' + y1, t.onTime], ['Delay it to April 1, ' + y2, t.delayed]].forEach(function (row) {
      var tr = document.createElement('tr'), o = row[1];
      cell(tr, row[0], 'th');
      cell(tr, money(o.y1)); cell(tr, money(o.y2)); cell(tr, money(o.t1)); cell(tr, money(o.t2)); cell(tr, money(o.t1 + o.t2));
      body.appendChild(tr);
    });
    var diff = (t.delayed.t1 + t.delayed.t2) - (t.onTime.t1 + t.onTime.t2);
    set('ybCompareNote', Math.abs(diff) < 0.5
      ? 'Both choices cost about the same in federal tax at these income levels.'
      : diff > 0
        ? 'Delaying stacks two RMDs into ' + y2 + ' and costs about ' + money(diff) + ' more in federal tax over the two years. Taking the first RMD by December 31, ' + y1 + ' is cheaper here.'
        : 'Delaying saves about ' + money(-diff) + ' in federal tax over the two years, because ' + y1 + ' income is taxed at a higher rate than the combined ' + y2 + ' income.');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ybForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
